import tiktoken

enc = tiktoken.encoding_for_model("gpt-4o")

def budget(system: str, history: list, max_ctx: int = 128000, reserve: int = 4000):
    sys_t = len(enc.encode(system))
    hist_t = sum(len(enc.encode(m)) for m in history)
    used = sys_t + hist_t
    remain = max_ctx - reserve - used          # reserve 留给模型本轮生成
    return {"system_tokens": sys_t, "history_tokens": hist_t,
            "used": used, "remain_for_reply": remain}

if __name__ == "__main__":
    history = [f"用户说：第{i}轮内容" for i in range(50)]
    print(budget("你是严谨的助手", history))

# 简化分词模拟：高频整体成 token，低频拆成字符（直观理解 BPE 思想）
VOCAB = {"我们": 0, "学习": 0, "智能": 0, "体": 0, "是": 0, "好": 0}

def tokenize(text):
    tokens, i = [], 0
    while i < len(text):
        matched = None
        for w in VOCAB:               # 贪心匹配最长词
            if text.startswith(w, i):
                matched = w
                break
        if matched:
            tokens.append(matched)
            i += len(matched)
        else:
            tokens.append(text[i])    # 未登录字单独成 token
            i += 1
    return tokens

if __name__ == "__main__":
    s = "我们学习智能体是好的"
    t = tokenize(s)
    print("tokens:", t)
    print("token 数:", len(t), "字符数:", len(s))

