def answer(query: str, confidence: float, knowledge: str) -> str:
    if confidence < 0.5:
        # 模型自己都不确定时，不直接答，转去检索或转人工
        return "置信度不足，已转检索/人工核实"
    if "最新" in query or "今天" in query:
        # 实时性问题模型大概率不知道，强制走工具
        return "实时信息，请调用搜索工具获取"
    return f"依据资料：{knowledge}"

if __name__ == "__main__":
    print(answer("公司成立于哪年？", 0.3, "..."))
    print(answer("退款政策是什么？", 0.9, "7天无理由"))

# 能力路由：算术交给代码，知识/实时交给模型或检索（离线模拟）
def route(task):
    import re
    if re.search(r"\d+\s*[\+\-\*]\s*\d+", task):
        expr = re.search(r"\d+\s*[\+\-\*]\s*\d+", task).group()
        return "code", str(eval(expr))          # 精确计算交给 Python
    if any(w in task for w in ["今天", "最新", "股价"]):
        return "retrieval", "需实时检索(占位)"
    return "llm", "由模型生成(占位)"

if __name__ == "__main__":
    for t in ["计算 12*8", "今天天气", "写首诗"]:
        kind, ans = route(t)
        print(f"{t} -> [{kind}] {ans}")

