# T 型能力评估：横杠(广度) + 竖杠(深度)，定位短板（离线）
def assess(breadth, depth):
    score = round(0.4 * breadth + 0.6 * depth, 1)
    if breadth < 6 and depth >= 7:
        gap = "宽底色不足，遇到跨域问题易卡"
    elif depth < 5:
        gap = "缺深专长，难做出有壁垒的系统"
    else:
        gap = "结构均衡，可深化某一方向"
    return score, gap

if __name__ == "__main__":
    for b, d in [(8, 8), (4, 9), (9, 3)]:
        s, g = assess(b, d)
        print(f"广度{b} 深度{d} -> 分{s} | {g}")
